#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "hash.h"
#include "vetor.h"
#include "fila.h"
#include "pilha.h"
#include "grafo.h"
typedef struct ReservaLivro {int codigo; Fila *fila;struct ReservaLivro *prox;} ReservaLivro;
static Fila *fila_do_livro(ReservaLivro **raiz,int codigo){for(ReservaLivro*r=*raiz;r;r=r->prox)if(r->codigo==codigo)return r->fila;ReservaLivro*r=malloc(sizeof(*r));if(!r)return NULL;r->fila=fila_criar();if(!r->fila){free(r);return NULL;}r->codigo=codigo;r->prox=*raiz;*raiz=r;return r->fila;}
static void liberar_reservas(ReservaLivro*r){while(r){ReservaLivro*t=r->prox;fila_liberar(r->fila);free(r);r=t;}}
int main(void){ReservaLivro *reservas=NULL;Hash*h=hash_criar(20011);Vetor v;vetor_iniciar(&v,16);Pilha*des=pilha_criar(),*ref=pilha_criar();Grafo*g=grafo_criar(6);for(int i=0;i<5;i++)grafo_ligar(g,i,i+1);grafo_ligar(g,0,2);grafo_ligar(g,2,4);int op=0;printf("BIBLIOTECA | Estruturas de Dados - Avaliacao 3\n");while(1){printf("\n1 Cadastrar livro | 2 Buscar codigo | 3 Listar por titulo\n4 Reservar | 5 Atender reserva | 6 Emprestar/devolver\n7 Desfazer | 8 Refazer | 9 Campi em ate 2 transferencias | 0 Sair\nOpcao: ");if(scanf("%d",&op)!=1||op==0)break;int c;Livro l,*encontrado;Acao a;switch(op){case 1:printf("Codigo e titulo (sem espacos): ");if(scanf("%d %63s",&l.codigo,l.titulo)!=2)break;l.emprestado=0;if(hash_buscar(h,l.codigo)){puts("Codigo existente.");break;}hash_inserir(h,l);vetor_adicionar(&v,l);puts("Cadastrado.");break;case 2:printf("Codigo: ");if(scanf("%d",&c)!=1)break;encontrado=hash_buscar(h,c);if(encontrado)printf("%d - %s - %s\n",c,encontrado->titulo,encontrado->emprestado?"emprestado":"disponivel");else puts("Nao encontrado.");break;case 3:{Vetor copia;vetor_iniciar(&copia,v.n);for(int i=0;i<v.n;i++)vetor_adicionar(&copia,v.dados[i]);vetor_ordenar(&copia);for(int i=0;i<copia.n;i++)printf("%d - %s\n",copia.dados[i].codigo,copia.dados[i].titulo);vetor_liberar(&copia);break;}case 4:printf("Codigo reservado: ");if(scanf("%d",&c)!=1)break;if(!hash_buscar(h,c))puts("Livro inexistente.");else{Fila *f=fila_do_livro(&reservas,c);if(f){fila_entrar(f,c);puts("Reserva adicionada a fila do livro.");}}break;case 5:printf("Codigo do livro: ");if(scanf("%d",&c)!=1)break;{Fila*f=fila_do_livro(&reservas,c);int proximo;if(f&&fila_sair(f,&proximo))printf("Proxima reserva atendida: livro %d\n",proximo);else puts("Sem reservas para este livro.");}break;case 6:printf("Codigo: ");if(scanf("%d",&c)!=1)break;encontrado=hash_buscar(h,c);if(!encontrado){puts("Inexistente.");break;}a.anterior=*encontrado;a.tipo=1;encontrado->emprestado=!encontrado->emprestado;a.posterior=*encontrado;pilha_empilhar(des,a);pilha_limpar(ref);printf("Estado: %s\n",encontrado->emprestado?"emprestado":"disponivel");break;case 7:if(pilha_desempilhar(des,&a)){encontrado=hash_buscar(h,a.anterior.codigo);if(encontrado)*encontrado=a.anterior;pilha_empilhar(ref,a);puts("Desfeito.");}else puts("Nada a desfazer.");break;case 8:if(pilha_desempilhar(ref,&a)){encontrado=hash_buscar(h,a.posterior.codigo);if(encontrado)*encontrado=a.posterior;pilha_empilhar(des,a);puts("Refeito.");}else puts("Nada a refazer.");break;case 9:printf("Campus origem (0 a 5): ");if(scanf("%d",&c)!=1)break;printf("Campi alcancaveis em ate 2 transferencias: %d\n",grafo_ate(g,c,2));break;default:puts("Opcao invalida.");}}
hash_liberar(h);vetor_liberar(&v);liberar_reservas(reservas);pilha_liberar(des);pilha_liberar(ref);grafo_liberar(g);return 0;}
